  ].join('\n');
  const user = `Fecha hoy: ${hoy}\nLead: ${l.Empresa} — ${l.Contacto} (${l.Cargo}) | Micro-ICP: ${l.Micro_ICP}\nTrigger: ${l.Trigger_Regulatorio} | Toques: ${l.Num_Toques} | Tipo de toque: ${toque}\nUltimo asunto: ${l.Asunto}\nRedacta el toque. Devuelve solo el JSON.`;
